  const grab = labels => { for (const lb of labels) { const m = text.match(new RegExp(lb + '\\s*[:：)]?\\s*([^\\n]+)')); if (m) { let v = m[1].trim().split(/\s{2,}|\||\(|（/)[0].trim(); if (v) return v; } } return ''; };
