  setV('cb-addr', grab(['사업장\\s*소재지', '사업장소재지', '소\\s*재\\s*지', '주\\s*소']));
  setV('cb-biztype', grab(['업\\s*태']));
  setV('cb-bizclass', grab(['종\\s*목']));
