        ['bizNo', 'corpName', 'ceo', 'addr', 'bizType', 'bizClass', 'contact', 'email'].forEach(k => { merged[k] = ti[k] || ex[k] || ''; });
        const patch = { taxInfo: merged }; if ((bizType || bizClass) && ctypeAutoOK(match.ctype)) patch.ctype = ct;   // 손으로 정한 대리점·별도는 지킨다
