    const q = Math.max(1, Math.round(_numv(r.querySelector('.ct-q').value) || 0) || 1);
    if (!(l > 0 && w > 0)) { toast('치수를 입력하세요'); return; }
    if (q < 2) { toast('한 부재를 연결하려면 수량을 2 이상으로 하거나, 2개 이상 체크하세요'); return; }
