    const qid = String(t.quoteId || '').trim(); if (!qid) return;
    const d = String(t.date || '').trim(); if (!d) return;
    if (!m[qid] || d > m[qid]) m[qid] = d;        // 나눠 출고했으면 마지막 출고일
