function addCostRow() { const c = el('ct-rows'); if (c) { c.insertAdjacentHTML('beforeend', costLineHtml({ gubun: '자재' })); costBasinRefresh(); } }
/* 화면을 새로 그린 뒤 세면대 줄들의 계산 결과를 한 번씩 채워준다 */
