  const g = items[0];
  const e = s => esc(s == null ? '' : String(s));
  const totJang = items.reduce((a, b) => a + (+b.jang || 0), 0);
  const totHebe = items.reduce((a, b) => a + (+b.hebe || 0), 0);
  // 문서번호: 출고일(YYYYMMDD) + 당일 출고 순번
