  const seq = Math.max(1, dayKeys.indexOf(key) + 1);
  const docNo = (g.date || '').replace(/-/g, '') + '-' + seq;
  const route = (g.dest || '') ? '다우세라믹 상차 →<br>' + e(g.dest) + ' 하차' : '';
