  const num = v => { const s = String(v == null ? '' : v).trim(); return s === '' ? null : (+s || 0); };
  // 앞뒤(폭 방향)
  let back;
  const ob = num(d.offB), of = num(d.offF);
  if (ob != null) back = ob; else if (of != null) back = W - bw - of; else back = (W - bw) / 2;
  const front = W - bw - back;
