  return `<text x="${x.toFixed(1)}" y="${y.toFixed(1)}" font-family="${BD_FONT}" font-size="${o.fs || 12}" fill="${o.c || '#111'}"`
    + ` text-anchor="${o.a || 'middle'}"${o.w ? ` font-weight="${o.w}"` : ''}${o.rot ? ` transform="rotate(${o.rot} ${x.toFixed(1)} ${y.toFixed(1)})"` : ''}>${esc(s)}</text>`;
